UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '무법항', `name_3` = 'Baie-du-Butin', `name_4` = 'Beutebucht', `name_5` = '藏宝海湾', `name_7` = 'Bahía del Botín', `name_8` = 'Bahía del Botín', `name_9` = 'Пиратская Бухта', `description_2` = '최근 급속한 성장을 이룬 무법항은 검은바다 해적단의 레빌가즈 남작이 다스리고 있는 해안 도시입니다. 스팀휘들 무역회사의 지부이며 붉은해적단과는 적대적 관계입니다.', `description_3` = 'Cette ville portuaire en pleine expansion est dirigée par le baron Revilgaz, des Écumeurs des Flots noirs. Ces derniers appartiennent au cartel Gentepression, et sont des ennemis mortels des boucaniers de la Voile sanglante.', `description_4` = 'In dieser blühenden Küstenstad', `description_5` = '一个由黑水海盗的头目，大财主里维加兹经营的繁荣的海港城市。它', `description_7` = 'Esta ciudad costera en auge está dirigida por el Barón Revilgaz, de los Asaltantes Aguasnegras. Son enemigos mortales de los Bucaneros Velasangre y forman parte del Cártel Bonvapor.', `description_8` = 'Esta ciudad costera en auge está dirigida por el Barón Revilgaz, de los Asaltantes Aguasnegras. Son enemigos mortales de los Bucaneros Velasangre y forman parte del Cártel Bonvapor.', `description_9` = 'В этом процветающем приморском городе правит барон Ревилгаз, разбойник Черноводья. Город входит в картель Хитрая Шестеренка и ведет войну с Кровавым парусом.' WHERE `id` = 21;
