UPDATE `faction` SET `reputation_race_mask_1` = 418, `reputation_race_mask_2` = 3149, `name_2` = '언더시티', `name_3` = 'Fossoyeuse', `name_4` = 'Unterstadt', `name_5` = '幽暗城', `name_7` = 'Entrañas', `name_8` = 'Entrañas', `name_9` = 'Подгород', `description_2` = '실바나스 윈드러너가 이끄는 포세이큰은 호드와 미약한 동맹 관계를 유지하고 있으며 로데론의 폐허 지하 깊숙한 곳에 도시를 건설하였습니다.', `description_3` = 'Dirigés par Sylvanas Coursevent, les Réprouvés ont établi une alliance ténue avec la Horde et se sont installés dans les vastes catacombes qui s’étendent sous les ruines de Lordaeron.', `description_4` = 'Angeführt von Sylvanas Windläu', `description_5` = '希尔瓦娜斯·风行者领导下的被遗忘者与部落之间建立起了微弱的同', `description_7` = 'Liderados por Sylvanas Brisaveloz, los Renegados han forjado una delicada alianza con la Horda y han asentado su capital en las vastas profundidades bajo las Ruinas de Lordaeron.', `description_8` = 'Liderados por Sylvanas Brisaveloz, los Renegados han forjado una delicada alianza con la Horda y han asentado su capital en las vastas profundidades bajo las Ruinas de Lordaeron.', `description_9` = 'Подземелья под руинами Лордерона населены Отрекшимися, заключившими хрупкий союз с Ордой. Ими правит леди Сильвана.' WHERE `id` = 68;
UPDATE `faction` SET `reputation_race_mask_1` = 3141, `reputation_race_mask_2` = 946, `name_2` = '다르나서스', `name_3` = 'Darnassus', `name_4` = 'Darnassus', `name_5` = '达纳苏斯', `name_7` = 'Darnassus', `name_8` = 'Darnassus', `name_9` = 'Дарнас', `description_2` = '나이트 엘프의 수도인 다르나서스는 텔드랏실 섬에 위치해 있습니다. 달의 여사제 티란데 위스퍼윈드가 이끌고 있습니다.', `description_3` = 'Située sur l’île de Teldrassil, cette capitale de l’Alliance est la demeure des elfes de la nuit. Elle est dirigée par la prêtresse de la Lune, Tyrande Murmevent.', `description_4` = 'Diese Hauptstadt der Allianz w', `description_5` = '坐落在泰达希尔岛上的联盟城市，暗夜精灵的首都，由月女祭司泰兰', `description_7` = 'Esta capital de la Alianza está habitada por los elfos de la noche y se encuentra en la isla de Teldrassil. Está gobernada por la Sacerdotisa de la Luna, Tyrande Susurravientos.', `description_8` = 'Esta capital de la Alianza está habitada por los elfos de la noche y se encuentra en la isla de Teldrassil. Está gobernada por la Sacerdotisa de la Luna, Tyrande Susurravientos.', `description_9` = 'Одна из столиц Альянса, расположенная на острове Тельдрассил и населенная ночными эльфами. Здесь правит жрица луны по имени Тиранда Шелест Ветра.' WHERE `id` = 69;
UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '비밀결사대', `name_3` = 'Syndicat', `name_4` = 'Syndikat', `name_5` = '辛迪加', `name_7` = 'La Hermandad', `name_8` = 'La Hermandad', `name_9` = 'Синдикат', `description_2` = '원래 인간 범죄 집단이었던 비밀결사대는 힐스브래드 구릉지와 알터랙 산맥 등지에서 활동하고 있습니다.', `description_3` = 'Cette organisation criminelle, composée d’une majorité d’humains, opère depuis les montagnes d’Alterac et les contreforts de Hautebrande.', `description_4` = 'Eine Verbrechensorganisation, ', `description_5` = '一个主要由人类组成的犯罪组织，目前占据着奥特兰克山脉与希尔斯', `description_7` = 'Una organización criminal mayoritariamente humana que opera principalmente en los alrededores de las montañas de Alterac y las Laderas de Trabalomas.', `description_8` = 'Una organización criminal mayoritariamente humana que opera principalmente en los alrededores de las montañas de Alterac y las Laderas de Trabalomas.', `description_9` = 'Преступное сообщество, организованное людьми. Действует почти на всей территории Альтеракских гор и предгорий Хилсбрада.' WHERE `id` = 70;
