UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '다크문 유랑단', `name_3` = 'Foire de Sombrelune', `name_4` = 'Dunkelmond-Jahrmarkt', `name_5` = '暗月马戏团', `name_7` = 'Feria de la Luna Negra', `name_8` = 'Feria de la Luna Negra', `name_9` = 'Ярмарка Новолуния', `description_2` = '신기하고 괴상한 것들을 선보이며 각지를 떠도는 다크문 유랑단은 엘윈 숲, 멀고어, 테로카르 숲에서 축제를 열곤 합니다.', `description_3` = 'Une foire itinérante qui présente des attractions étranges et extraordinaires. On la trouve souvent dans les forêts d’Elwynn et de Terrokar, ainsi qu\'en Mulgore.', `description_4` = 'Dieser umherziehende Jahrmarkt', `description_5` = '一个向全世界展示着各类珍奇异宝的旅行马戏团。他们经常会访问艾', `description_7` = 'Es una feria ambulante que hace espectáculos con lo extraño y lo extraordinario. Suelen dejarse ver por el Bosque de Elwynn, Mulgore y el Bosque de Terokkar.', `description_8` = 'Es una feria ambulante que hace espectáculos con lo extraño y lo extraordinario. Suelen dejarse ver por el Bosque de Elwynn, Mulgore y el Bosque de Terokkar.', `description_9` = 'Бродячая ярмарка, на которой можно найти много странного и диковинного. Часто останавливается в Элвиннском лесу, Мулгоре и Тероккарском лесу.' WHERE `id` = 909;
UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '노즈도르무 혈족', `name_3` = 'Progéniture de Nozdormu', `name_4` = 'Brut Nozdormus', `name_5` = '诺兹多姆的子嗣', `name_7` = 'Linaje de Nozdormu', `name_8` = 'Linaje de Nozdormu', `name_9` = 'Род Ноздорму', `description_2` = '청동용군단의 후예들인 노즈도르무 혈족은 시간의 수호자이며 필멸의 종족들에게 별다른 관심을 보이지 않습니다.', `description_3` = 'Ces descendants du Vol de bronze sont les gardiens du temps, et ne se préoccupent que très peu des races mortelles.', `description_4` = 'Die Abkömmlinge des bronzenen ', `description_5` = '青铜龙军团的后代，时间的守卫者，对凡人种族漠不关心。', `description_7` = 'Los descendientes del Vuelo Bronce son los guardianes del tiempo y poco les importan los mortales.', `description_8` = 'Los descendientes del Vuelo Bronce son los guardianes del tiempo y poco les importan los mortales.', `description_9` = 'Эти потомки бронзовых драконов охраняют само Время и не слишком интересуются делами смертных.' WHERE `id` = 910;
