UPDATE `faction` SET `reputation_race_mask_1` = 946, `reputation_race_mask_2` = 3149, `name_2` = '트랜퀼리엔', `name_3` = 'Tranquillien', `name_4` = 'Tristessa', `name_5` = '塔奎林', `name_7` = 'Tranquillien', `name_8` = 'Tranquillien', `name_9` = 'Транквиллион', `description_2` = '한때 하이 엘프 마을이었던 트랜퀼리엔은 스컬지의 쿠엘탈라스 침공 이후 버려졌습니다. 이제 유령의 땅에서 스컬지를 몰아내려는 포세이큰과 블러드 엘프의 보금자리가 되었습니다.', `description_3` = 'Tranquillien était jadis une paisible cité elfe. Abandonnée lorsque le Fléau a envahi Quel’Thalas, elle a été reprise par les Réprouvés et les elfes de sang qui s’efforcent de chasser le Fléau des Terres fantômes.', `description_4` = 'Einstige Stadt der Hochelfen, ', `description_5` = '塔奎林曾是一座高等精灵的城镇，但是在天灾军团入侵奎尔萨拉斯之', `description_7` = 'En sus tiempos una ciudad de elfos nobles, Tranquillien quedó abandonada después de que la Plaga invadiera Quel\'Thalas. Ahora ha sido reclamada por los Renegados y los elfos de sangre, quienes intentan eliminar de las Tierras Fantasma a la Plaga.', `description_8` = 'En sus tiempos una ciudad de elfos nobles, Tranquillien quedó abandonada después de que la Plaga invadiera Quel\'Thalas. Ahora ha sido reclamada por los Renegados y los elfos de sangre, quienes intentan eliminar de las Tierras Fantasma a la Plaga.', `description_9` = 'Этот город высших эльфов был брошен вскоре после нападения Плети на Кель\'Талас. Сейчас в нем живут Отрекшиеся и эльфы крови, стремящиеся освободить Призрачные земли.' WHERE `id` = 922;
