UPDATE `faction` SET `reputation_race_mask_1` = 2125, `name_2` = '엑소다르', `name_3` = 'Exodar', `name_4` = 'Die Exodar', `name_5` = '埃索达', `name_7` = 'El Exodar', `name_8` = 'El Exodar', `name_9` = 'Экзодар', `description_2` = '드레나이가 아제로스에 타고 온 나루 함선입니다. 하늘안개 섬에 추락해 있지만 지금은 고귀한 드레나이 종족의 고향으로서의 역할을 수행하고 있습니다.', `description_3` = 'Le vaisseau naaru qui a conduit les draeneï en Azeroth. Bien que naufragé dans l\'archipel de Brume-azur, il sert de capitale à ce noble peuple.', `description_4` = 'Das Schiff der Naaru, das die ', `description_5` = '将德莱尼人带到艾泽拉斯世界来的纳鲁飞船，目前搁浅在秘蓝岛上。', `description_7` = 'La nave naaru que trajo a los draenei a Azeroth. A pesar de estar varada en las Islas Bruma Azur, sirve de hogar a esta noble raza.', `description_8` = 'La nave naaru que trajo a los draenei a Azeroth. A pesar de estar varada en las Islas Bruma Azur, sirve de hogar a esta noble raza.', `description_9` = 'Корабль наару, доставивший дренеев на Азерот. Стоящий на островах Лазурной Дымки, он служит домом этой благородной расы.' WHERE `id` = 930;
UPDATE `faction` SET `name_2` = 'Test Faction (not a real faction)', `name_3` = 'Faction de test (fausse faction)', `name_4` = 'Test Faction (not a ', `name_5` = 'Test Faction (not a ', `name_7` = 'Facción de prueba (no es real)', `name_8` = 'Facción de prueba (no es real)', `name_9` = 'Тестовая фракция (несуществующая)', `description_2` = 'This faction only exists to test the editing of faction names and descriptions...', `description_3` = 'Faction dédiée aux tests d\'éditions des noms et descriptions de faction...', `description_4` = 'This faction only exists to te', `description_5` = 'This faction only exists to te', `description_7` = 'Esta facción solo existe para probar a editar nombres de facción y descripciones.', `description_8` = 'Esta facción solo existe para probar a editar nombres de facción y descripciones.', `description_9` = 'Эта фракция предназначена для тестирования названий и описаний фракций...' WHERE `id` = 931;
UPDATE `faction` SET `reputation_race_mask_1` = 2259, `name_2` = '알도르 사제회', `name_3` = 'L\'Aldor', `name_4` = 'Die Aldor', `name_5` = '奥尔多', `name_7` = 'Los Aldor', `name_8` = 'Los Aldor', `name_9` = 'Алдоры', `description_2` = '알도르 사제회는 드레나이 사제 계급의 고대 모임으로 과거엔 벨렌이 이끌었으나 현재는 대여사제 이샤나가 이끌고 있습니다. 그들은 샤타르로 알려진 샤트라스의 나루를 섬기고 있습니다. 점술가 길드와는 경쟁 관계에 있습니다.', `description_3` = 'Autrefois dirigé par Velen, l’Aldor est un ordre antique de prêtres draeneï. Son chef actuel est la grande prêtresse Ishanah. Il sert les Sha’tar, les naaru de Shattrath, et est en rivalité avec les Clairvoyants.', `description_4` = 'Als uralter Orden von Draeneip', `description_5` = '一个古老的德莱尼祭司组织，起初由维伦领导。现在他们在高阶女祭', `description_7` = 'Es una antigua orden de sacerdotes draenei dirigida antaño por Velen. Los Aldor están actualmente bajo el mando de la suma sacerdotisa Ishanah. Son sirvientes de los naaru de la Ciudad de Shattrath, conocidos como los Sha\'tar. Son rivales de los Arúspices.', `description_8` = 'Es una antigua orden de sacerdotes draenei dirigida antaño por Velen. Los Aldor están actualmente bajo el mando de la suma sacerdotisa Ishanah. Son sirvientes de los naaru de la Ciudad de Shattrath, conocidos como los Sha\'tar. Son rivales de los Arúspices.', `description_9` = 'Этот древний орден дренейских жрецов, основанный Веленом, сейчас возглавляет верховная жрица Ишана. Представители Алдоров служат наару в Шаттрате и враждуют с Провидцами.' WHERE `id` = 932;
UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '무역연합', `name_3` = 'Le Consortium', `name_4` = 'Das Konsortium', `name_5` = '星界财团', `name_7` = 'El Consorcio', `name_8` = 'El Consorcio', `name_9` = 'Консорциум', `description_2` = '연합왕자 하라매드가 이끌고 있는 무역연합은 아웃랜드의 부를 노리고 몰려든 에테리얼 밀수꾼과 무역상, 도둑으로 구성된 연합 지부입니다.', `description_3` = 'Dirigé par le prince-nexus Haramad, le Consortium est un cartel de contrebandiers, de négociants et de voleurs éthériens, unis dans une alliance assez lâche et venus en Outreterre pour tirer profit de ses richesses.', `description_4` = 'Das Konsortium, geführt von Ne', `description_5` = '由星界巨商哈拉麦德领导的星界财团是一个结构松散的商业联盟，其', `description_7` = 'Bajo el mando del príncipe-nexo Haramad, el Consorcio es un cártel de afiliación sin excesivo rigor de contrabandistas etéreos, comerciantes y ladrones que han llegado a Terrallende para beneficiarse de sus riquezas.', `description_8` = 'Bajo el mando del príncipe-nexo Haramad, el Consorcio es un cártel de afiliación sin excesivo rigor de contrabandistas etéreos, comerciantes y ladrones que han llegado a Terrallende para beneficiarse de sus riquezas.', `description_9` = 'Консорциум принца Харамада – слабоорганизованное сообщество астральных контрабандистов, торговцев и воров, пришедших в Запределье в погоне за прибылью.' WHERE `id` = 933;
UPDATE `faction` SET `reputation_race_mask_1` = 2259, `name_2` = '점술가 길드', `name_3` = 'Les Clairvoyants', `name_4` = 'Die Seher', `name_5` = '占星者', `name_7` = 'Los Arúspices', `name_8` = 'Los Arúspices', `name_9` = 'Провидцы', `description_2` = '점술가 길드는 마력으로 이끄는 캘타스의 길을 거부한 반체제 블러드 엘프 단체로 현자 보렌살이 이끌고 있습니다. 이들은 알도르의 우려에도 불구하고 최근 샤트라스의 나루와 손을 잡았습니다.', `description_3` = 'Voren’thal le Voyant dirige les elfes de sang dissidents qui ont rejeté la vision de Kael’thas. Au grand désarroi de l\'Aldor, ils se sont joints aux naaru de Shattrath.', `description_4` = 'Voren\'thal der Seher ist der A', `description_5` = '由先知沃雷塔尔领导的这群血精灵拒绝跟随凯尔萨斯。他们加入了沙', `description_7` = 'Voren\'thal el Vidente lidera a los elfos de sangre disidentes que han rechazado el camino hacia el poder de Kael\'thas. Se han unido a los naaru de Ciudad de Shattrath para consternación de los Aldor.', `description_8` = 'Voren\'thal el Vidente lidera a los elfos de sangre disidentes que han rechazado el camino hacia el poder de Kael\'thas. Se han unido a los naaru de Ciudad de Shattrath para consternación de los Aldor.', `description_9` = 'Эту группу эльфов крови, отвергших путь Кель\'таса, возглавляет Ворен\'таль Провидец. К большому неудовольствию Алдоров, Провидцы заключили союз с наару из Шаттрата.' WHERE `id` = 934;
UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '샤타르', `name_3` = 'Les Sha\'tar', `name_4` = 'Die Sha\'tar', `name_5` = '沙塔尔', `name_7` = 'Los Sha\'tar', `name_8` = 'Los Sha\'tar', `name_9` = 'Ша\'тар', `description_2` = '샤타르는 재건된 샤트라스를 지배하고 있는 강력한 나루로 이루어진 단체입니다. 알도르 사제회와 점술가 길드의 도움으로 일리단과 불타는 군단에 맞서 전투를 이끌고 있습니다.', `description_3` = 'Les Sha’tar forment un groupe de puissants naaru, qui règne sur la cité reconstruite de Shattrath. Avec l\'aide de l\'Aldor et des Clairvoyants, ils dirigent la lutte contre Illidan et la Légion ardente.', `description_4` = 'Die Sha\'tar sind eine Gruppe m', `description_5` = '沙塔尔是一群统治沙塔斯城的强大纳鲁人的组织。在奥尔多和占星者', `description_7` = 'Los Sha\'tar son un grupo de poderosos naaru que gobiernan la reconstruida Ciudad de Shattrath. Con el apoyo de los Aldor y los Arúspices lideran la batalla contra Illidan y la Legión Ardiente.', `description_8` = 'Los Sha\'tar son un grupo de poderosos naaru que gobiernan la reconstruida Ciudad de Shattrath. Con el apoyo de los Aldor y los Arúspices lideran la batalla contra Illidan y la Legión Ardiente.', `description_9` = 'Группа могущественных наару, которая правит вновь отстроенным городом Шаттрат. Совместно с Алдорами и Провидцами они сражаются против Иллидана и Пылающего Легиона.' WHERE `id` = 935;
