UPDATE `faction` SET `reputation_race_mask_1` = 946, `reputation_race_mask_2` = 3149, `name_2` = '마그하르', `name_3` = 'Mag\'har', `name_4` = 'Die Mag\'har', `name_5` = '玛格汉', `name_7` = 'Los Mag\'har', `name_8` = 'Los Mag\'har', `name_9` = 'Маг\'хары', `description_2` = '은둔 생활을 하고 있는 이 갈색 피부의 오크들은 악마의 타락으로부터 벗어날 수 있었습니다. 이들은 전통적인 삶의 방식을 고수하면서 아웃랜드에 닥친 변화의 바람에 맞서고 있습니다.', `description_3` = 'Ces orcs à la peau brune vivent reclus et ont échappé à toute corruption démoniaque. Ils ont conservé leur mode de vie traditionnel malgré tous les bouleversements survenus en Outreterre.', `description_4` = 'Diese zurückgezogene Gruppe br', `description_5` = '这群隐居的棕皮兽人逃脱了恶魔的腐蚀，并在天崩地裂的外域中保持', `description_7` = 'Este grupo de huraños orcos de piel marrón ha escapado de la corrupción demoníaca. Ha mantenido su forma de vida tradicional a pesar de los grandes cambios en Terrallende.', `description_8` = 'Este grupo de huraños orcos de piel marrón ha escapado de la corrupción demoníaca. Ha mantenido su forma de vida tradicional a pesar de los grandes cambios en Terrallende.', `description_9` = 'Замкнутая группа бурокожих орков, сумевшая полностью оградить себя от влияния демонов. Несмотря на все перемены, они хранят верность традициям своего народа.' WHERE `id` = 941;
UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '세나리온 원정대', `name_3` = 'Expédition cénarienne', `name_4` = 'Expedition des Cenar', `name_5` = '塞纳里奥远征队', `name_7` = 'Expedición Cenarion', `name_8` = 'Expedición Cenarion', `name_9` = 'Кенарийская экспедиция', `description_2` = '세나리온 원정대는 아웃랜드에서 살아 남은 생명체 연구를 위해 세나리온 의회에서 파견한 원정대입니다. 세나리온 원정대는 어둠의 문이 열린 후 빠른 시간 내에 규모를 확장하고 자주권을 확보하였습니다.', `description_3` = 'Une troupe d’explorateurs envoyée en Outreterre par le Cercle cénarien, afin d’étudier les formes de vie survivantes. L’expédition cénarienne a rapidement grossi et gagné en autonomie depuis l\'ouverture de la Porte des ténèbres.', `description_4` = 'Eine Truppe von Forschern, die', `description_5` = '塞纳里奥议会派往外域研究生态的探险队。在黑暗之门开启后，远征', `description_7` = 'El Círculo Cenarion envió una partida de exploración a Terrallende para estudiar las formas de vida supervivientes. La expedición Cenarion ha ganado en tamaño y autonomía desde la apertura de El Portal Oscuro.', `description_8` = 'El Círculo Cenarion envió una partida de exploración a Terrallende para estudiar las formas de vida supervivientes. La expedición Cenarion ha ganado en tamaño y autonomía desde la apertura de El Portal Oscuro.', `description_9` = 'Экспедиция Круга Кенария, организованная для изучения фауны Запределья. Со времени открытия Темного портала ее численность и независимость заметно увеличились.' WHERE `id` = 942;
