UPDATE `faction` SET `reputation_race_mask_1` = 3149, `reputation_race_mask_2` = 946, `name_2` = '명예의 요새', `name_3` = 'Bastion de l\'Honneur', `name_4` = 'Ehrenfeste', `name_5` = '荣耀堡', `name_7` = 'Bastión del Honor', `name_8` = 'Bastión del Honor', `name_9` = 'Оплот Чести', `description_2` = '명예의 요새는 얼라이언스 정예군인 로서의 후예가 드레노어에 처음 도착했을 때 건설한 요새이며 지옥불 반도의 전초기지로서 역할을 수행하고 있습니다. 지금은 스톰윈드와 아이언포지의 군대가 파견되어 주둔 중입니다.', `description_3` = 'Cet avant-poste des Flammes infernales est la place forte de ce qui reste des Fils de Lothar, les vétérans de l’Alliance qui ont, les premiers, posé le pied sur Draenor. Des armées venues de Forgefer et de Hurlevent sont en train de les rejoindre.', `description_4` = 'Die noch Verbliebenen der Söhn', `description_5` = '这座前哨基地坐落在地狱火半岛上，由第一批深入德拉诺的联盟精英', `description_7` = 'Vestigios de los Hijos de Lothar, los primeros veteranos de la Alianza que llegaron a Draenor, se han aferrado firmemente a esta avanzada de Fuego Infernal. Ahora se han unido a los ejércitos de Ventormenta y Forjaz.', `description_8` = 'Vestigios de los Hijos de Lothar, los primeros veteranos de la Alianza que llegaron a Draenor, se han aferrado firmemente a esta avanzada de Fuego Infernal. Ahora se han unido a los ejércitos de Ventormenta y Forjaz.', `description_9` = 'Эту заставу основали спутники Сынов Лотара – закаленные ветераны Альянса, первыми пришедшие в Дренор. Сейчас к ним присоединились воины из Штормграда и Стальгорна.' WHERE `id` = 946;
UPDATE `faction` SET `reputation_race_mask_1` = 946, `reputation_race_mask_2` = 3149, `name_2` = '스랄마', `name_3` = 'Thrallmar', `name_4` = 'Thrallmar', `name_5` = '萨尔玛', `name_7` = 'Thrallmar', `name_8` = 'Thrallmar', `name_9` = 'Траллмар', `description_2` = '스랄의 명에 의해 어둠의 문을 넘어 지옥불 반도에 도착한 원정대는 성채를 건설하고 스랄마라 이름 지었습니다. 스랄마는 아웃랜드에서 활동 중인 호드의 작전 기지 역할을 수행하고 있습니다.', `description_3` = 'L’expédition envoyée à travers la Porte des ténèbres par Thrall a bâti une forteresse sur la péninsule des Flammes infernales. Thrallmar sert de base d’opérations à la plupart des activités de la Horde en Outreterre.', `description_4` = 'Die Expedition, die von Thrall', `description_5` = '由萨尔派出的远征军在地狱火半岛建立的要塞。萨尔玛是部落在外域', `description_7` = 'La expedición que Thrall enviara a través del Portal Oscuro ha construido un fuerte en la Península del Fuego Infernal. Thrallmar sirve de base de operaciones para muchas de las actividades de la Horda en Terrallende.', `description_8` = 'La expedición que Thrall enviara a través del Portal Oscuro ha construido un fuerte en la Península del Fuego Infernal. Thrallmar sirve de base de operaciones para muchas de las actividades de la Horda en Terrallende.', `description_9` = 'Эту крепость на Полуострове Адского Пламени возвела экспедиция в Темный портал, снаряженная Траллом. Траллмар служит опорным пунктом Орды в Запределье.' WHERE `id` = 947;
