UPDATE `faction` SET `name_2` = '보랏빛 눈의 감시자', `name_3` = 'L\'Œil pourpre', `name_4` = 'Das Violette Auge', `name_5` = '紫罗兰之眼', `name_7` = 'El Ojo Violeta', `name_8` = 'El Ojo Violeta', `name_9` = 'Аметистовое Око', `description_2` = '보랏빛 눈의 감시자는 메디브와 그의 활동을 감시하기 위해 설립된 키린 토의 비밀 단체입니다.', `description_3` = 'Une secte secrète du Kirin Tor, fondée pour espionner Medivh et ses activités.', `description_4` = 'Eine geheime Sekte der Kirin T', `description_5` = '一个由肯瑞托为了调查麦迪文和监视他的活动而建立的秘密组织。', `description_7` = 'Una secta secreta del Kirin Tor fundada para espiar a Medivh y sus actividades.', `description_8` = 'Una secta secreta del Kirin Tor fundada para espiar a Medivh y sus actividades.', `description_9` = 'Тайное братство Кирин-Тора, созданное для слежения за Медивом.' WHERE `id` = 967;
