UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '스포어가르', `name_3` = 'Sporeggar', `name_4` = 'Sporeggar', `name_5` = '孢子村', `name_7` = 'Esporaggar', `name_8` = 'Esporaggar', `name_9` = 'Спореггар', `description_2` = '스포어가르는 아웃랜드 토착 종족인 평화로운 버섯인간이 살고 있는 마을입니다. 이 마을은 장가르 습지대의 남부 늪지대에 위치하고 있습니다.', `description_3` = 'Les sporelins sont un peuple d’hommes-champignons paisibles, originaires de l’Outreterre. Ils vivent dans les tourbières méridionales du marécage de Zangar.', `description_4` = 'Die Sporlinge sind ein vornehm', `description_5` = '生活在外域的孢子人是一个非常温和的种族。他们的家园就坐落在赞', `description_7` = 'Los esporinos son una raza en su mayoría pacífica de hombres champiñón nativos de Terrallende. Su hogar se encuentra en las ciénagas del sur de la Marisma de Zangar.', `description_8` = 'Los esporinos son una raza en su mayoría pacífica de hombres champiñón nativos de Terrallende. Su hogar se encuentra en las ciénagas del sur de la Marisma de Zangar.', `description_9` = 'Спорлинги – мирная раса, издавна населяющая Запределье. Их дом находится в южной части Зангартопи.' WHERE `id` = 970;
