UPDATE `faction` SET `reputation_race_mask_1` = 3149, `reputation_race_mask_2` = 946, `name_2` = '쿠레나이', `name_3` = 'Kurenaï', `name_4` = 'Kurenai', `name_5` = '库雷尼', `name_7` = 'Kurenai', `name_8` = 'Kurenai', `name_9` = 'Куренай', `description_2` = '이들은 타락에서 다시 회복된 드레나이들입니다. 이 뒤틀린 드레나이들은 아웃랜드의 지배 계급으로부터 탈출하여 나그란드에 정착하였습니다. 거기서 이들은 자신들의 운명을 되찾으려는 노력을 기울이고 있습니다.', `description_3` = 'Ce mot signifie « rachetés » en draeneï. Après avoir échappé au joug des esclavagistes de l\'Outreterre, ces Roués se sont installés en Nagrand. C\'est là qu\'ils cherchent à redécouvrir leur destinée.', `description_4` = 'Draeneiisch für ""erlöst"". Di', `description_5` = '在德莱尼语中意为“得到救赎”。这些从各种奴役和控制中逃出来的', `description_7` = 'En draenei significa ""redimidos."" Estos Tábidos han escapado de la esclavitud en Terrallende y han hecho de Nagrand su hogar. Ahí esperan redescubrir su destino.', `description_8` = 'En draenei significa ""redimidos."" Estos Tábidos han escapado de la esclavitud en Terrallende y han hecho de Nagrand su hogar. Ahí esperan redescubrir su destino.', `description_9` = 'Дреней – значит ""Искупленный"". Эти Падшие, сумевшие вырваться из рабства и избравшие своим домом Награнд, стремятся вновь обрести свою судьбу.' WHERE `id` = 978;
