UPDATE `faction` SET `name_2` = '고난의 거리', `name_3` = 'Ville basse', `name_4` = 'Unteres Viertel', `name_5` = '贫民窟', `name_7` = 'Bajo Arrabal', `name_8` = 'Bajo Arrabal', `name_9` = 'Нижний Город', `description_2` = '고난의 거리에는 각지에서 모여든 다양한 종족의 피난민들이 거주하고 있습니다. 이들을 돕기 위한 도움의 손길이 주민들 사이에 빠르게 퍼지고 있습니다.', `description_3` = 'Les réfugiés qui habitent Shattrath sont de diverses races et origines. Lorsque l\'on vient en aide à un habitant de la Ville basse, la nouvelle se répand vite.', `description_4` = 'Die Flüchtlinge von Shattrath ', `description_5` = '来自各个地方、各个种族的避难者在沙塔斯城的聚集地。在贫民窟中', `description_7` = 'Los refugiados de Shattrath proceden de diferentes razas y contextos. Los relatos de buenas acciones se extienden rápidamente entre los habitantes del Bajo Arrabal.', `description_8` = 'Los refugiados de Shattrath proceden de diferentes razas y contextos. Los relatos de buenas acciones se extienden rápidamente entre los habitantes del Bajo Arrabal.', `description_9` = 'Среди изгнанников, нашедших приют в Шаттрате, встречаются представители самых разных рас и народов. Но стоит вам помочь одному из них, как об этом узнают все.' WHERE `id` = 1011;
UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '잿빛혓바닥 결사단', `name_3` = 'Ligemort cendrelangue', `name_4` = 'Die Todeshörigen', `name_5` = '灰舌死誓者', `name_7` = 'Juramorte Lengua de ceniza', `name_8` = 'Juramorte Lengua de ceniza', `name_9` = 'Пеплоусты-служители', `description_2` = '잿빛혓바닥 결사단은 뒤틀린 드레나이 부족 중 정예로 구성되어 있으며 일리단과 연합을 맺고 있습니다. 이 결사대는 아카마의 가장 충성스러운 부대원으로 구성되어 있으며 비밀스러운 음모를 수행하고 있습니다.', `description_3` = 'L’élite de la tribu des Roués des Cendrelangues, officiellement alliée avec Illidan. Les ligemorts sont les lieutenants favoris d’Akama, et connaissent les mystérieuses motivations de leur chef.', `description_4` = 'Die Elite des Stammes der Zers', `description_5` = '来自破碎者灰舌部族的精英勇士，表面上与伊利丹结盟。这些勇士是', `description_7` = 'La élite de la tribu de los Tábidos se conoce como los Lengua de ceniza, aliados oficiales de Illidan. Los Juramorte son los tenientes más leales de Akama y tienen conocimiento de las misteriosas motivaciones de su líder.', `description_8` = 'La élite de la tribu de los Tábidos se conoce como los Lengua de ceniza, aliados oficiales de Illidan. Los Juramorte son los tenientes más leales de Akama y tienen conocimiento de las misteriosas motivaciones de su líder.', `description_9` = 'Элита Сломленных, официально заключившая союз с Иллиданом. Пеплоусты – преданные сподвижники Акамы, готовые поддержать любые начинания своего господина.' WHERE `id` = 1012;
UPDATE `faction` SET `name_2` = '어둠달의 영혼들 1', `name_3` = 'Esprits d\'Ombrelune 1', `name_4` = 'Geister von Schatten', `name_5` = 'Spirits of Shadowmoo', `name_7` = 'Espíritus de Sombraluna 1', `name_8` = 'Espíritus de Sombraluna 1', `name_9` = 'Духи Призрачной Луны 1' WHERE `id` = 1013;
