UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '황천의 용군단', `name_3` = 'Aile-du-Néant', `name_4` = 'Netherschwingen', `name_5` = '灵翼之龙', `name_7` = 'Ala Abisal', `name_8` = 'Ala Abisal', `name_9` = 'Крылья Пустоты', `description_2` = '이 희귀한 용족은 황천의 에너지를 받은 데스윙의 검은용군단 알로부터 탄생하였습니다. 이제 이들은 부모로부터 물려 받은 파괴적인 천성의 그늘에 가려진 자신들의 정체성을 찾으려하고 있습니다.', `description_3` = 'Cette portée de dragons peu commune est issue des œufs du Vol noir d\'Aile de mort, imprégnés des pures énergies du Néant. Ils cherchent maintenant à retrouver leur identité, au-delà des ombres de l\'héritage délétère de leur père.', `description_4` = 'Diese ungewöhnlichen Drachen e', `description_5` = '这种罕见的龙是死亡之翼的后代，受到原始的虚空能量影响后发生了', `description_7` = 'Esta inusual camada de dragones nació de los huevos del Vuelo Negro de Alamuerte y está imbuida de energías del vacío puras. Ahora buscan su identidad más allá de las sombras de la destructora herencia de su padre.', `description_8` = 'Esta inusual camada de dragones nació de los huevos del Vuelo Negro de Alamuerte y está imbuida de energías del vacío puras. Ahora buscan su identidad más allá de las sombras de la destructora herencia de su padre.', `description_9` = 'Необычный вид черных драконов, произошедший от потомков Смертокрыла, яйца которых были подвержены влиянию энергии Пустоты. Сейчас они ищут себя, пытаясь избавиться от мрачного наследия своего отца.' WHERE `id` = 1015;
