UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '오그릴라', `name_3` = 'Ogri\'la', `name_4` = 'Ogri\'la', `name_5` = '奥格瑞拉', `name_7` = 'Ogri\'la', `name_8` = 'Ogri\'la', `name_9` = 'Огри\'ла', `description_2` = '오그릴라의 개화된 오우거들은 칼날 산맥 서쪽에 자리잡고 있습니다. 이들은 오그릴라 주변에 있는 에펙시스 수정으로 인해 오우거만의 잔인한 본성을 초월할 수 있었습니다.', `description_3` = 'Les citoyens éclairés d\'Ogri\'la ont élu domicile dans la partie ouest des Tranchantes, où la proximité des cristaux apogides leur a permis de transcender la brutalité de leur nature d\'ogres.', `description_4` = 'Die erleuchteten Bewohner von ', `description_5` = '聪明而开化的奥格瑞拉食人魔居住在刀锋山的西部区域，那里富产的', `description_7` = 'Los iluminados habitantes de Ogri\'la han creado su hogar en las Montañas Filospada occidentales. La proximidad a los cristales de ápices ha hecho que trascienda su bruta naturaleza de ogros.', `description_8` = 'Los iluminados habitantes de Ogri\'la han creado su hogar en las Montañas Filospada occidentales. La proximidad a los cristales de ápices ha hecho que trascienda su bruta naturaleza de ogros.', `description_9` = 'Поселение Огри\'ла находится на западе Клинковых гор. Влияние апекситовых кристаллов позволило его жителям заметно превзойти в развитии обычных огров.' WHERE `id` = 1038;
