UPDATE `faction` SET `reputation_race_mask_1` = 946, `reputation_race_mask_2` = 3149, `name_2` = '복수의 대리인', `name_3` = 'La Main de la vengeance', `name_4` = 'Die Hand der Rache', `name_5` = '复仇之手', `name_7` = 'La Mano de la Venganza', `name_8` = 'La Mano de la Venganza', `name_9` = 'Карающая Длань', `description_2` = '아서스에 대한 언더시티의 복수심의 상징인 이들은 실바나스 윈드러너의 명령에 따라 최근까지 연구하고 있었던 죽음의 역병을 가져왔습니다.', `description_3` = 'Sylvanas Coursevent a chargé ces Réprouvés de venger Fossoyeuse en infligeant la dernière mutation de leur peste mortelle à Arthas.', `description_4` = 'Eine Gruppe der Verlassenen, d', `description_5` = '这支由希尔瓦娜斯·风行者派遣的被遗忘者势力想要在诺森德散播他', `description_7` = 'Sylvanas Brisaveloz ha encomiado a los Renegados la tarea de vengarse de Arthas en nombre de Entrañas utilizando su mortífera peste.', `description_8` = 'Sylvanas Brisaveloz ha encomiado a los Renegados la tarea de vengarse de Arthas en nombre de Entrañas utilizando su mortífera peste.', `description_9` = 'Отрекшиеся, откомандированные Сильваной Ветрокрылой для отмщения Артасу с помощью новейшего вида смертельной чумы.' WHERE `id` = 1067;
UPDATE `faction` SET `reputation_race_mask_1` = 3149, `reputation_race_mask_2` = 946, `name_2` = '탐험가 연맹', `name_3` = 'Ligue des explorateurs', `name_4` = 'Forscherliga', `name_5` = '探险者协会', `name_7` = 'Liga de Expedicionarios', `name_8` = 'Liga de Expedicionarios', `name_9` = 'Лига исследователей', `description_2` = '이들은 드워프 종족의 기원을 밝혀내고자 티탄의 유물을 수집하고 있습니다. 최근 노스렌드로 건너와 다양한 고고학 유적에 대한 조사를 시작했습니다.', `description_3` = 'Cette organisation cherche à découvrir les origines de la race des nains en rassemblant les reliques des titans. Leurs recherches les plus récentes les ont conduit à explorer différents sites archéologiques du Norfendre.', `description_4` = 'Diese Organisation strebt dana', `description_5` = '这个组织致力于通过发掘泰坦遗留下来的古器追寻矮人种族的起源。', `description_7` = 'Esta organización busca el origen de la raza de los enanos reuniendo artefactos de los titanes. Su investigación más reciente les ha llevado hasta varias excavaciones arqueológicas en Rasganorte.', `description_8` = 'Esta organización busca el origen de la raza de los enanos reuniendo artefactos de los titanes. Su investigación más reciente les ha llevado hasta varias excavaciones arqueológicas en Rasganorte.', `description_9` = 'Эта организация стремится пролить свет на происхождение расы дворфов, собирая реликвии Титанов. Результаты последних научных исследований побудили их заняться раскопками в Нордсколе.' WHERE `id` = 1068;
