UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '칼루아크', `name_3` = 'Les Kalu\'aks', `name_4` = 'Die Kalu\'ak', `name_5` = '卡鲁亚克', `name_7` = 'Los Kalu\'ak', `name_8` = 'Los Kalu\'ak', `name_9` = 'Калу\'ак', `description_2` = '투스카르는 낚시와 고래잡이로 생계를 꾸려 나가는 강인하지만 온순한 종족입니다. 최근 마을을 침략한 강력한 위협에 맞서고 있는 투스카르는 자신들을 도와줄 동맹을 찾고 있습니다.', `description_3` = 'Les roharts sont un peuple endurant mais pacifique, qui vit de la pêche et de la chasse à la baleine. Leurs villages ont récemment été violemment attaqués, et ils accueillent volontiers tous les alliés qui leur viennent en aide.', `description_4` = 'Die Tuskarr sind ein zähes, je', `description_5` = '海象人是坚韧而和平的种族，通过捕鲸和捕鱼谋生。他们的家园最近', `description_7` = 'Los colmillarr son una gente dura, pero pacífica que basan su sustento en la pesca y la caza de ballenas. Últimamente sus asentamientos han sufrido unos ataques feroces y dan la bienvenida a cualquier aliado que quiera ayudarles.', `description_8` = 'Los colmillarr son una gente dura, pero pacífica que basan su sustento en la pesca y la caza de ballenas. Últimamente sus asentamientos han sufrido unos ataques feroces y dan la bienvenida a cualquier aliado que quiera ayudarles.', `description_9` = 'Клыкарры – суровый, но мирный народ, который существует за счет рыбалки и охоты на китов. Недавно их поселения подверглись ожесточенным нападениям, поэтому клыкарры рады любым союзникам, предлагающим помощь.' WHERE `id` = 1073;
