UPDATE `faction` SET `reputation_race_mask_1` = 3149, `reputation_race_mask_2` = 946, `reputation_race_mask_3` = 3149, `reputation_race_mask_4` = 946, `name_2` = '키린 토', `name_3` = 'Kirin Tor', `name_4` = 'Kirin Tor', `name_5` = '肯瑞托', `name_7` = 'Kirin Tor', `name_8` = 'Kirin Tor', `name_9` = 'Кирин-Тор', `description_2` = '달라란의 마법사와 대마법사들은 점점 고조되는 푸른용군단과 스컬지의 위협에 맞서 자신들의 도시를 노스렌드의 중심부로 이동시켰습니다.', `description_3` = 'Les mages et les archimages qui gouvernent la cité de Dalaran. Devant les menaces croissantes du vol draconique bleu et du Fléau, ils ont transporté leur cité au cœur du Norfendre.', `description_4` = 'Die Magier und Erzmagier, welc', `description_5` = '统治达拉然的法师和大法师们。由于蓝龙军团和亡灵天灾造成的威胁', `description_7` = 'Los magos y archimagos que gobiernan la ciudad de Dalaran. Enfrentados a las crecientes amenazas del Vuelo Azul y la Plaga, ahora han mudado su ciudad al corazón de Rasganorte.', `description_8` = 'Los magos y archimagos que gobiernan la ciudad de Dalaran. Enfrentados a las crecientes amenazas del Vuelo Azul y la Plaga, ahora han mudado su ciudad al corazón de Rasganorte.', `description_9` = 'Верховные и простые маги, управляющие Далараном. В свете появления новых опасностей со стороны рода синих драконов и Плети они переместили свой город в сердце Нордскола.' WHERE `id` = 1090;
UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '고룡쉼터 사원 용군단', `name_3` = 'L\'Accord du Repos du ver', `name_4` = 'Der Wyrmruhpakt', `name_5` = '龙眠联军', `name_7` = 'El Acuerdo del Reposo del Dragón', `name_8` = 'El Acuerdo del Reposo del Dragón', `name_9` = 'Драконий союз', `description_2` = '푸른용군단이 마법의 힘을 사용하는 모든 필멸의 존재에 맞서 격변을 일으키자 다른 용군단들은 붉은용군단의 지도 아래 엇나간 동료 용군단과 싸움을 시작했습니다.', `description_3` = 'Avec le soulèvement violent du vol draconique bleu contre tous les utilisateurs mortels de la magie, les vols draconiques restants se sont regroupés sous la bannière du vol draconique rouge, pour combattre leurs frères égarés.', `description_4` = 'Angesichts der Aggression des ', `description_5` = '由于蓝龙军团粗暴地干涉凡人种族使用魔法的权利，其余的龙族不得', `description_7` = 'Con el violento levantamiento del Vuelo Azul contra todos los usuarios de magia mortales, los vuelos restantes se han unido bajo el liderazgo del Vuelo Rojo para combatir a sus parientes díscolos.', `description_8` = 'Con el violento levantamiento del Vuelo Azul contra todos los usuarios de magia mortales, los vuelos restantes se han unido bajo el liderazgo del Vuelo Rojo para combatir a sus parientes díscolos.', `description_9` = 'Яростное неприятие родом синих драконов всех смертных, использующих магию, заставило другие роды объединиться под крылом красных драконов для борьбы со своими заблудшими собратьями.' WHERE `id` = 1091;
