UPDATE `faction` SET `reputation_race_mask_1` = 3149, `reputation_race_mask_2` = 946, `name_2` = '은빛 서약단', `name_3` = 'Le Concordat argenté', `name_4` = 'Der Silberbund', `name_5` = '银色盟约', `name_7` = 'El Pacto de Plata', `name_8` = 'El Pacto de Plata', `name_9` = 'Серебряный союз', `description_2` = '블러드 엘프의 키린 토 합류를 거부한 하이 엘프의 군사 조직으로 베리사 윈드러너의 지도 아래 연합하여 노스렌드에서 얼라이언스 군대와 손을 잡았습니다.', `description_3` = 'Un groupe militant de hauts-elfes qui refuse l\'admission d\'elfes de sang au Kirin Tor. Ils se sont unis sous la bannière de Vereesa Coursevent et ont rejoint les forces de l\'Alliance dans le Norfendre.', `description_4` = 'Ein militanter Kern von Hochel', `description_5` = '这支高等精灵中的精锐部队拒绝让血精灵进入肯瑞托。他们联合在温', `description_7` = 'Un núcleo de elfos nobles militantes que rechazan la admisión de los elfos de sangre en el Kirin Tor. Se han juntado bajo el estandarte de Vereesa Brisaveloz y se han unido a las fuerzas de la Alianza en Rasganorte.', `description_8` = 'Un núcleo de elfos nobles militantes que rechazan la admisión de los elfos de sangre en el Kirin Tor. Se han juntado bajo el estandarte de Vereesa Brisaveloz y se han unido a las fuerzas de la Alianza en Rasganorte.', `description_9` = 'Военная верхушка высших эльфов, не согласившаяся с принятием эльфов крови в Кирин-Тор. Возглавляемые Верисой Ветрокрылой, они присоединились к силам Альянса в Нордсколе.' WHERE `id` = 1094;
