UPDATE `faction` SET `name_2` = '칠흑의 기사단', `name_3` = 'Chevaliers de la Lame d\'ébène', `name_4` = 'Ritter der Schwarzen', `name_5` = '黑锋骑士团', `name_7` = 'Caballeros de la Espada de Ébano', `name_8` = 'Caballeros de la Espada de Ébano', `name_9` = 'Рыцари Черного Клинка', `description_2` = '리치 왕의 마수에서 해방된 죽음의 기사들은 대영주 다리온 모그레인의 깃발 아래 뭉쳐 리치 왕에 맞서고 있습니다.', `description_3` = 'Libérés de l\'emprise du roi-liche, ses anciens chevaliers de la mort se sont regroupés pour l\'affronter sous la bannière du généralissime Darion Mograine.', `description_4` = 'Frei von der Knechtschaft durc', `description_5` = '在脱离了巫妖王的控制之后，这些曾经效命于他的死亡骑士联合起来', `description_7` = 'Liberados del control del Rey Exánime, sus otrora caballeros de la Muerte se han reagrupado contra él bajo el estandarte del alto señor Darion Mograine.', `description_8` = 'Liberados del control del Rey Exánime, sus otrora caballeros de la Muerte se han reagrupado contra él bajo el estandarte del alto señor Darion Mograine.', `description_9` = 'Оставив службу у Короля-лича, часть рыцарей смерти объединилась против своего бывшего хозяина под предводительством верховного лорда Дариона Могрейна.' WHERE `id` = 1098;
