UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '광란의심장일족', `name_3` = 'Tribu Frénécœur', `name_4` = 'Stamm der Wildherzen', `name_5` = '狂心氏族', `name_7` = 'Tribu Corazón Frenético', `name_8` = 'Tribu Corazón Frenético', `name_9` = 'Племя Бешеного Сердца', `description_2` = '스컬지의 침공으로 고향에서 쫓겨난 이 사나운 울바르 부족은 숄라자르 분지에서 어렵게 새로운 터전을 일구고 있습니다. 이들은 공격적인 본성으로 인해 점쟁이 조합 등 다양한 골록 부족과 대립하고 있습니다.', `description_3` = 'Chassée de ses terres par le Fléau, cette redoutable tribu de varleus compte faire du bassin de Sholazar son nouveau foyer. Le tempérament agressif de ses membres leur vaut des démêlés avec les diverses tribus de gorlocs regroupées sous le nom d\'Oracles.', `description_4` = 'Von der Geißel aus ihrer Heima', `description_5` = '这群凶猛的狼獾人被天灾军团追杀，偶然来到了索拉查盆地，遂决定', `description_7` = 'Expulsados de su tierra por la Plaga, esta feroz tribu de wolvar decidió instalarse en la Cuenca de Sholazar. Su naturaleza agresiva les ha enemistado con las tribus górloc conocidas en conjunto como los Oráculos.', `description_8` = 'Expulsados de su tierra por la Plaga, esta feroz tribu de wolvar decidió instalarse en la Cuenca de Sholazar. Su naturaleza agresiva les ha enemistado con las tribus górloc conocidas en conjunto como los Oráculos.', `description_9` = 'Изгнанное из родных земель Плетью, это свирепое племя волчеров остановилось в Низине Шолазар с намерением обосноваться там. В силу своей агрессивной природы они вступили в конфликт с племенами горлоков, называемых Оракулами.' WHERE `id` = 1104;
UPDATE `faction` SET `reputation_race_mask_1` = 4095, `name_2` = '점쟁이 조합', `name_3` = 'Les Oracles', `name_4` = 'Die Orakel', `name_5` = '神谕者', `name_7` = 'Los Oráculos', `name_8` = 'Los Oráculos', `name_9` = 'Оракулы', `description_2` = '숄라자르 분지의 골록은 (비록 거의 이해하고 있지는 못하지만) 스스로를 티탄 기술의 수호자라 칭하는 파충류 생명체입니다. 최근 골록은 울바르와의 영토 전쟁에 깊이 휘말리고 있습니다.', `description_3` = 'Les gorlocs du bassin de Sholazar sont des créatures reptiliennes qui se considèrent comme les gardiens des vestiges de la technologie des titans dans la région (même s’ils la comprennent mal). Ils sont en conflit territorial avec les varleus.', `description_4` = 'Die Gorlocs des Scholazarbecke', `description_5` = '索拉查盆地的鳄鱼人将自己视为该区域中存留的泰坦科技的守护者（', `description_7` = 'Los górlocs de la Cuenca de Sholazar son una raza de reptiles que se consideran los guardianes de la tecnología titánica restante en la zona (aunque casi no la comprenden). Están sumergidos en una creciente guerra territorial con los wolvar.', `description_8` = 'Los górlocs de la Cuenca de Sholazar son una raza de reptiles que se consideran los guardianes de la tecnología titánica restante en la zona (aunque casi no la comprenden). Están sumergidos en una creciente guerra territorial con los wolvar.', `description_9` = 'Горлоки Низины Шолазар – раса рептилий, считающих себя хранителями того немногого, что осталось от технологий титанов в этой зоне. Они находятся в состоянии обостряющейся территориальной войны с волчерами.' WHERE `id` = 1105;
UPDATE `faction` SET `name_2` = '은빛십자군', `name_3` = 'La Croisade d\'argent', `name_4` = 'Argentumkreuzzug', `name_5` = '银色北伐军', `name_7` = 'Cruzada Argenta', `name_8` = 'Cruzada Argenta', `name_9` = 'Серебряный Авангард', `description_2` = '티리온 폴드링이 이끄는 은빛십자군은 리치 왕의 군대에 맞서는 은빛 성기사단과 은빛 여명회의 연합군입니다.', `description_3` = 'Menée par Tirion Fordring, la Croisade d\'argent regroupe les membres d\'une Main d\'argent reformée et ceux de l\'Aube d\'argent, dans le but de vaincre une bonne fois pour toutes les troupes du roi-liche.', `description_4` = 'Der Argentumkreuzzug ist ein Z', `description_5` = '提里奥·弗丁领导的银色北伐军是由白银之手骑士团和银色黎明重组', `description_7` = 'Liderada por Tirion Vadín, la Cruzada Argenta aúna la reformada Orden de la Mano de Plata con El Alba Argenta en el ataque final contra las fuerzas del Rey Exánime.', `description_8` = 'Liderada por Tirion Vadín, la Cruzada Argenta aúna la reformada Orden de la Mano de Plata con El Alba Argenta en el ataque final contra las fuerzas del Rey Exánime.', `description_9` = 'Ведомый Тирионом Фордрингом, Серебряный Авангард объединил в себе реформированный орден Серебряной Длани и орден Серебряного Рассвета для борьбы против армий Короля-лича.' WHERE `id` = 1106;
