UPDATE `faction` SET `reputation_race_mask_1` = 946, `reputation_race_mask_2` = 3149, `name_2` = '선리버', `name_3` = 'Les Saccage-soleil', `name_4` = 'Die Sonnenhäscher', `name_5` = '夺日者', `name_7` = 'Los Atracasol', `name_8` = 'Los Atracasol', `name_9` = 'Похитители Солнца', `description_2` = '예전부터 달라란과 접촉이 금지되었던 호드는 대마법사 에이타스 선리버의 노력으로 달라란에 들어오게 되었다. 선리버의 추종자들은 그의 이름을 따서 지은 선리버 성소를 지키는 임무를 수행하고 있다.', `description_3` = 'Traditionnellement exclue de Dalaran, la Horde a fini par y être admise grâce aux efforts de l\'archimage Aethas Saccage-soleil. Ses adeptes ont repris son nom et veillent sur le quartier appelé Sanctuaire de Saccage-soleil.', `description_4` = 'Durch die Anstrengungen des Er', `description_5` = '在大法师艾萨斯·夺日者的努力下，一贯被达拉然据之门外的部落也', `description_7` = 'Tradicionalmente no se admitía en Dalaran a la Horda, pero han sido admitidos en la ciudad mediante los esfuerzos del archimago Aethas Atracasol. Sus seguidores han retomado su nombre y velan por la sala conocida como Santuario Atracasol.', `description_8` = 'Tradicionalmente no se admitía en Dalaran a la Horda, pero han sido admitidos en la ciudad mediante los esfuerzos del archimago Aethas Atracasol. Sus seguidores han retomado su nombre y velan por la sala conocida como Santuario Atracasol.', `description_9` = 'Путь в Даларан всегда был заказан для Орды, но благодаря стараниям верховного мага Этаса Похитителя Солнца ей все же открыли доступ в город. Последователи Этаса назвали в честь своего благодетеля целый район города – Прибежище Похитителя Солнца.' WHERE `id` = 1124;
