UPDATE `faction` SET `reputation_race_mask_1` = 3149, `reputation_race_mask_2` = 946, `name_2` = '서릿결부족 드워프', `name_3` = 'Les Givre-nés', `name_4` = 'Die Frosterben', `name_5` = '霜脉矮人', `name_7` = 'Los Natoescarcha', `name_8` = 'Los Natoescarcha', `name_9` = 'Зиморожденные', `description_2` = '이 수수께끼에 싸인 서릿결부족 드워프는 폭풍우 봉우리에 살고 있습니다. 최근 그들은 탐험가 연맹의 몇몇 드워프와 우호적인 관계를 맺어, 마을을 찾는 얼라이언스를 반가이 맞이합니다.', `description_3` = 'Cette mystérieuse race de nains de givre a élu domicile dans les pics Foudroyés. Ils se sont récemment alliés à la Ligue des explorateurs et accueillent les membres de l\'Alliance dans leurs habitations.', `description_4` = 'Dieses geheimnisvolle Eiszwerg', `description_5` = '这个神秘的冰霜矮人种族定居在风暴峭壁。他们最近与探险者协会成', `description_7` = 'Esta misteriosa raza de enanos de escarcha tiene su hogar en Las Cumbres Tormentosas. Hace poco han entablado amistad con miembros de la Liga de Expedicionarios y acogido a miembros de la Alianza en sus tierras.', `description_8` = 'Esta misteriosa raza de enanos de escarcha tiene su hogar en Las Cumbres Tormentosas. Hace poco han entablado amistad con miembros de la Liga de Expedicionarios y acogido a miembros de la Alianza en sus tierras.', `description_9` = 'Загадочная раса снежных дворфов, живущих на Грозовой Гряде. Недавно они подружились с путешественниками из Лиги Исследователей и рады приветствовать друзей Альянса в своих поселениях.' WHERE `id` = 1126;
