UPDATE `faction` SET `name_2` = '잿빛 선고단', `name_3` = 'Le Verdict des cendres', `name_4` = 'Das Äscherne Verdikt', `name_5` = '灰烬审判军', `name_7` = 'El Veredicto Cinéreo', `name_8` = 'El Veredicto Cinéreo', `name_9` = 'Пепельный союз', `description_2` = '티리온 폴드링과 다리온 모그레인의 협정에 따라 은빛십자군과 칠흑의 기사단은 리치 왕이 쓰러질 때까지 서로의 입장 차이를 잠시 접어두고 공동으로 얼음왕관 성채 공격 작전을 펼치기로 했습니다.', `description_3` = 'Tirion Fordring et Darion Mograine ont passé un accord. La Croisade d’argent et les chevaliers de la Lame d’ébène ont mis de côté leurs différends pour attaquer la citadelle de la Couronne de glace… et anéantir le roi-liche.', `description_4` = 'Durch einen Pakt von Tirion Fo', `description_5` = '在提里奥·弗丁与达里安·莫格莱尼的共同协议下，银色北伐军与黑', `description_7` = 'Por un pacto entre Tirion Vadín y Darion Mograine, la Cruzada Argenta y los Caballeros de la Espada de Ébano han dejado a un lado sus diferencias durante el ataque a la Ciudadela de la Corona de Hielo hasta que se acabe con el Rey Exánime.', `description_8` = 'Por un pacto entre Tirion Vadín y Darion Mograine, la Cruzada Argenta y los Caballeros de la Espada de Ébano han dejado a un lado sus diferencias durante el ataque a la Ciudadela de la Corona de Hielo hasta que se acabe con el Rey Exánime.', `description_9` = 'По условиям договора между Тирионом Фордрингом и Дарионом Могрейном Серебряный Авангард и Рыцари Черного Клинка обязуются отложить решение разногласий до тех пор, пока Король-лич не будет повержен.' WHERE `id` = 1156;
